@extends('layouts.app') @section('content')<h2>Keranjang Belanja</h2>@if(!$cart)<p class="bg-white p-4">Keranjang kosong. <a href="/">Mulai belanja</a></p>@else<div class="bg-white rounded p-3">@foreach($cart as $id=>$qty)@if(isset($products[$id]))<div class="d-flex align-items-center gap-3 border-bottom py-3 flex-wrap"><div class="me-auto"><b>{{ $products[$id]->name }}</b><div>Rp{{ number_format($products[$id]->price,0,',','.') }}</div></div><form method="post" action="{{ route('cart.update',$id) }}" class="d-flex gap-2">@csrf @method('PATCH')<input class="form-control" style="width:80px" type="number" name="quantity" value="{{ $qty }}"><button class="btn btn-outline-success btn-sm">Ubah</button></form><form method="post" action="{{ route('cart.remove',$id) }}">@csrf @method('DELETE')<button class="btn btn-link text-danger">Hapus</button></form></div>@endif @endforeach</div><div class="bg-white p-3 mt-3 d-flex justify-content-between"><b>Total Rp{{ number_format($total,0,',','.') }}</b><a class="btn btn-success" href="/checkout">Checkout</a></div>@endif @endsection